import React, { useState } from 'react';
import { 
  BrainCircuit, Upload, LogOut, AlertTriangle, CheckCircle2, 
  TrendingUp, Shield, User, GraduationCap, Users, 
  ArrowRight, Activity, BookOpen, HeartPulse, Wallet
} from 'lucide-react';

const API_URL = "http://127.0.0.1:8000";

export default function App() {
  // --- GLOBAL STATE ---
  const [user, setUser] = useState(null);
  const [data, setData] = useState([]); // This stores the AI results for the whole session
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // --- SHARED LOGIC ---
  const handleLogin = (role) => {
    setUser({ role, name: role.charAt(0).toUpperCase() + role.slice(1) });
  };

  const onUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    const formData = new FormData();
    formData.append('file', file);
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${API_URL}/analyze`, { method: 'POST', body: formData });
      if (!response.ok) throw new Error("Check if Backend (main.py) is running.");
      const result = await response.json();
      setData(result);
    } catch (err) {
      setError("AI Engine Offline. Please start your Python FastAPI server.");
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER LOGIN SCREEN ---
  if (!user) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6">
        <div className="bg-[#0f172a] p-12 rounded-[3rem] shadow-2xl border border-slate-800 w-full max-w-md text-center">
          <BrainCircuit className="mx-auto text-indigo-500 w-16 h-16 mb-6" />
          <h1 className="text-white text-4xl font-black mb-2 tracking-tighter">SUCCESS<span className="text-indigo-500">PREDICT</span></h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mb-10">AI Socioeconomic Monitor</p>
          
          <div className="space-y-3">
            {[
              { id: 'admin', label: 'Administrator', icon: <Shield size={18}/> },
              { id: 'teacher', label: 'Faculty / Teacher', icon: <User size={18}/> },
              { id: 'student', label: 'Student Portal', icon: <GraduationCap size={18}/> }
            ].map(role => (
              <button 
                key={role.id}
                onClick={() => handleLogin(role.id)}
                className="w-full py-4 px-6 bg-slate-800 hover:bg-indigo-600 text-white rounded-2xl font-bold flex items-center justify-between group transition-all"
              >
                <span className="flex items-center gap-3">{role.icon} {role.label}</span>
                <ArrowRight size={16} className="opacity-0 group-hover:opacity-100 transition-all" />
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // --- RENDER MAIN INTERFACE ---
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans">
      {/* GLOBAL NAVBAR */}
      <nav className="bg-white/80 backdrop-blur-md border-b sticky top-0 z-50 px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2 font-black text-xl tracking-tighter">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white"><BrainCircuit size={18}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        
        <div className="flex items-center gap-6">
          <div className="text-right">
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest leading-none mb-1">{user.role}</p>
            <p className="text-sm font-bold text-slate-700 leading-none">{user.name} Account</p>
          </div>
          <button onClick={() => {setUser(null); setData([]);}} className="bg-red-50 text-red-500 p-2.5 rounded-xl hover:bg-red-100 transition-all">
            <LogOut size={20} />
          </button>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto p-8">
        
        {/* VIEW 1: ADMINISTRATOR (DATA UPLOAD & ANALYSIS) */}
        {user.role === 'admin' && (
          <div className="space-y-8">
            <div className="bg-indigo-600 rounded-[2.5rem] p-10 text-white shadow-xl shadow-indigo-200 flex flex-col lg:flex-row justify-between items-center gap-8">
              <div className="max-w-xl">
                <h2 className="text-4xl font-black mb-4">ML Analysis Hub</h2>
                <p className="text-indigo-100 text-lg leading-relaxed">
                  Upload CSV records to trigger the AI prediction engine. The system evaluates income, distance, and attendance to identify students needing intervention.
                </p>
              </div>
              <label className="shrink-0 bg-white text-indigo-600 px-10 py-5 rounded-2xl font-black text-lg cursor-pointer hover:scale-105 transition-transform shadow-lg">
                <input type="file" className="hidden" onChange={onUpload} accept=".csv" />
                {loading ? "AI Processing..." : "Process Dataset"}
              </label>
            </div>

            {error && <div className="bg-red-50 border border-red-200 p-4 rounded-xl text-red-600 font-bold">{error}</div>}

            <div className="grid gap-4">
              {data.map((student, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl border border-slate-100 flex items-center justify-between hover:shadow-md transition-all">
                  <div className="flex items-center gap-5">
                    <div className={`p-4 rounded-2xl ${student.at_risk ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-500'}`}>
                      {student.at_risk ? <AlertTriangle size={24} /> : <CheckCircle2 size={24} />}
                    </div>
                    <div>
                      <h4 className="font-bold text-lg">{student.name}</h4>
                      <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Risk Score: {student.risk_score}%</p>
                    </div>
                  </div>
                  <div className="flex-1 px-10 hidden md:block">
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-sm italic text-slate-600 font-medium">
                      <span className="text-indigo-600 font-black uppercase text-[10px] block mb-1">Recommended Solution:</span>
                      "{student.solution}"
                    </div>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${student.at_risk ? 'bg-red-500 text-white' : 'bg-green-500 text-white'}`}>
                    {student.at_risk ? 'At Risk' : 'Stable'}
                  </div>
                </div>
              ))}
              {data.length === 0 && !loading && <EmptyState message="Please upload student data to begin." />}
            </div>
          </div>
        )}

        {/* VIEW 2: TEACHER (INTERVENTION LIST) */}
        {user.role === 'teacher' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <StatCard title="Assigned Students" value={data.length} icon={<Users />} color="bg-indigo-50 text-indigo-600" />
              <StatCard title="Critical Risk" value={data.filter(s => s.at_risk).length} icon={<Activity />} color="bg-red-50 text-red-600" />
              <StatCard title="Interventions" value="0" icon={<HeartPulse />} color="bg-green-50 text-green-600" />
            </div>

            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <h3 className="text-2xl font-black mb-6">Faculty Intervention Queue</h3>
              <div className="space-y-4">
                {data.filter(s => s.at_risk).map((student, i) => (
                  <div key={i} className="flex items-center justify-between p-6 border rounded-2xl border-slate-100 hover:bg-slate-50 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-400">{student.name[0]}</div>
                      <div>
                        <p className="font-bold text-slate-800">{student.name}</p>
                        <p className="text-xs text-red-500 font-bold uppercase">Intervention Required</p>
                      </div>
                    </div>
                    <button className="bg-indigo-600 text-white px-5 py-2 rounded-xl font-bold text-xs hover:bg-indigo-700 transition-all">
                      Schedule Counseling
                    </button>
                  </div>
                ))}
                {data.filter(s => s.at_risk).length === 0 && <EmptyState message="No at-risk students currently assigned to you." />}
              </div>
            </div>
          </div>
        )}

        {/* VIEW 3: STUDENT (PERSONAL PROGRESS) */}
        {user.role === 'student' && (
          <div className="max-w-2xl mx-auto space-y-8">
            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl text-center space-y-6">
              <div className="w-24 h-24 bg-green-50 rounded-full flex items-center justify-center mx-auto text-green-500">
                <CheckCircle2 size={48} />
              </div>
              <div>
                <h2 className="text-3xl font-black mb-2">My Academic Status</h2>
                <p className="text-slate-500 font-medium italic">Data processed via SuccessPredict AI Engine</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                  <Wallet className="mx-auto mb-3 text-indigo-500" />
                  <p className="text-[10px] font-black text-slate-400 uppercase">Subsidy Eligibility</p>
                  <p className="font-bold text-slate-800">Reviewing</p>
                </div>
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                  <BookOpen className="mx-auto mb-3 text-indigo-500" />
                  <p className="text-[10px] font-black text-slate-400 uppercase">Study Status</p>
                  <p className="font-bold text-slate-800">Stable</p>
                </div>
              </div>
              <p className="text-xs text-slate-400 px-6">Your data is monitored for early detection of barriers to graduation. Contact the registrar for more details.</p>
            </div>
          </div>
        )}

      </main>
    </div>
  );
}

// --- HELPER COMPONENTS (To keep things clean) ---

function StatCard({ title, value, icon, color }) {
  return (
    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-5">
      <div className={`p-4 rounded-2xl ${color}`}>{icon}</div>
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{title}</p>
        <h3 className="text-3xl font-black leading-none">{value}</h3>
      </div>
    </div>
  );
}

function EmptyState({ message }) {
  return (
    <div className="text-center py-20 bg-white rounded-[3rem] border border-dashed border-slate-200">
      <TrendingUp size={48} className="mx-auto text-slate-200 mb-4" />
      <p className="text-slate-400 font-bold">{message}</p>
    </div>
  );
}
